import{_ as t,o,c as e,a2 as l}from"./chunks/framework.BXzK3EA4.js";const q=JSON.parse('{"title":"工作经历问题准备","description":"工作经历类问题 = 离职原因 + 业务方向 + 个人规划 三件套。 准备思路：每道题按\\"事实结论 + 积极动机\\"两层回答。","frontmatter":{},"headers":[],"relativePath":"面试/工作经历/index.md","filePath":"面试/工作经历/index.md","lastUpdated":1793113268000}'),r={name:"面试/工作经历/index.md"};function i(s,a,n,h,u,d){return o(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="工作经历问题准备" tabindex="-1">工作经历问题准备 <a class="header-anchor" href="#工作经历问题准备" aria-label="Permalink to &quot;工作经历问题准备&quot;">​</a></h1><blockquote><p>工作经历类问题 = <strong>离职原因 + 业务方向 + 个人规划</strong> 三件套。 准备思路：每道题按&quot;<strong>事实结论</strong> + <strong>积极动机</strong>&quot;两层回答。</p></blockquote><h2 id="一、为什么看新机会" tabindex="-1">一、为什么看新机会？ <a class="header-anchor" href="#一、为什么看新机会" aria-label="Permalink to &quot;一、为什么看新机会？&quot;">​</a></h2><blockquote><p>⚠️ 这是面试必问题，也是最容易踩雷的题。原则：<strong>说对现公司真实不满（中性）+ 目标岗位吸引点</strong>。</p></blockquote><h3 id="万能公式" tabindex="-1">万能公式 <a class="header-anchor" href="#万能公式" aria-label="Permalink to &quot;万能公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[对现公司真实不满] + [目标岗位吸引点]</span></span></code></pre></div><h3 id="_5-个参考话术-按实际情况选-1-2-个" tabindex="-1">5 个参考话术（按实际情况选 1-2 个） <a class="header-anchor" href="#_5-个参考话术-按实际情况选-1-2-个" aria-label="Permalink to &quot;5 个参考话术（按实际情况选 1-2 个）&quot;">​</a></h3><h4 id="话术-a-业务方向" tabindex="-1">话术 A：业务方向 <a class="header-anchor" href="#话术-a-业务方向" aria-label="Permalink to &quot;话术 A：业务方向&quot;">​</a></h4><blockquote><p>&quot;现公司业务方向有些调整，新项目不太能发挥我的经验。我比较想找一个<strong>业务更聚焦、用户量更大</strong>的平台。&quot;</p></blockquote><h4 id="话术-b-技术成长" tabindex="-1">话术 B：技术成长 <a class="header-anchor" href="#话术-b-技术成长" aria-label="Permalink to &quot;话术 B：技术成长&quot;">​</a></h4><blockquote><p>&quot;现公司技术栈相对稳定了（Vue 2 老项目维护为主），我想找一个<strong>技术更新迭代更快、有挑战</strong>的环境。&quot;</p></blockquote><h4 id="话术-c-职业发展" tabindex="-1">话术 C：职业发展 <a class="header-anchor" href="#话术-c-职业发展" aria-label="Permalink to &quot;话术 C：职业发展&quot;">​</a></h4><blockquote><p>&quot;目前团队规模比较小，<strong>主导机会有限</strong>。希望去一个<strong>更大的平台</strong>，能带团队、主导更大的项目。&quot;</p></blockquote><h4 id="话术-d-业务-行业" tabindex="-1">话术 D：业务/行业 <a class="header-anchor" href="#话术-d-业务-行业" aria-label="Permalink to &quot;话术 D：业务/行业&quot;">​</a></h4><blockquote><p>&quot;现公司业务比较窄（主要是 XX），我想<strong>拓展行业经验</strong>，比如对贵公司的 XX 业务方向（金融/电商/SaaS）很感兴趣。&quot;</p></blockquote><h4 id="话术-e-异地-家庭" tabindex="-1">话术 E：异地/家庭 <a class="header-anchor" href="#话术-e-异地-家庭" aria-label="Permalink to &quot;话术 E：异地/家庭&quot;">​</a></h4><blockquote><p>&quot;家庭原因计划<strong>换城市发展</strong> / 通勤距离想缩短，对贵公司的<strong>位置</strong>比较满意。&quot;</p></blockquote><h3 id="❌-不要说的话" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;现公司领导不行 / 同事太差 / 加班太多&quot;</li><li>❌ &quot;薪资太低&quot;</li><li>❌ &quot;被裁员 / 公司倒闭&quot;</li><li>❌ &quot;想躺平&quot;</li><li>❌ 任何对前雇主的负面评价</li></ul><hr><h2 id="二、去年绩效情况" tabindex="-1">二、去年绩效情况？ <a class="header-anchor" href="#二、去年绩效情况" aria-label="Permalink to &quot;二、去年绩效情况？&quot;">​</a></h2><h3 id="万能公式-1" tabindex="-1">万能公式 <a class="header-anchor" href="#万能公式-1" aria-label="Permalink to &quot;万能公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[绩效等级] + [关键贡献] + [对比标准]</span></span></code></pre></div><h3 id="参考话术" tabindex="-1">参考话术 <a class="header-anchor" href="#参考话术" aria-label="Permalink to &quot;参考话术&quot;">​</a></h3><h4 id="话术-a-绩效好" tabindex="-1">话术 A（绩效好） <a class="header-anchor" href="#话术-a-绩效好" aria-label="Permalink to &quot;话术 A（绩效好）&quot;">​</a></h4><blockquote><p>&quot;去年绩效 <strong>A / Top 20%</strong>，主导了 XXX 项目（具体成果数据化），独立完成了 XXX（技术深度）。在部门 30 人里排前几名。&quot;</p></blockquote><h4 id="话术-b-绩效一般" tabindex="-1">话术 B（绩效一般） <a class="header-anchor" href="#话术-b-绩效一般" aria-label="Permalink to &quot;话术 B（绩效一般）&quot;">​</a></h4><blockquote><p>&quot;绩效 <strong>B+</strong>，按期完成了本任务。今年我在 XXX 上有突破（比如独立做了组件库 / 接口自动化 / 性能优化），希望今年能拿更好的绩效。&quot;</p></blockquote><h3 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h3><ul><li>避免说&quot;不清楚&quot; / &quot;我不太关注绩效&quot;</li><li>即使绩效一般也要拿出<strong>具体贡献</strong>支撑</li><li>主动说自己&quot;做了什么&quot;而不是&quot;被打分&quot;</li></ul><hr><h2 id="三、找工作倾向" tabindex="-1">三、找工作倾向？ <a class="header-anchor" href="#三、找工作倾向" aria-label="Permalink to &quot;三、找工作倾向？&quot;">​</a></h2><h3 id="万能公式-2" tabindex="-1">万能公式 <a class="header-anchor" href="#万能公式-2" aria-label="Permalink to &quot;万能公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[岗位类型] + [业务方向] + [团队阶段] + [薪酬范围]</span></span></code></pre></div><h3 id="_7-年经验参考话术" tabindex="-1">7 年经验参考话术 <a class="header-anchor" href="#_7-年经验参考话术" aria-label="Permalink to &quot;7 年经验参考话术&quot;">​</a></h3><blockquote><p>&quot;<strong>岗位</strong>：高级 / 资深前端开发，能独立负责复杂模块。<br><strong>业务</strong>：B 端 SaaS / 中后台系统 / 数据可视化（这 3 个选 1-2 个）。<br><strong>团队</strong>：30-200 人规模、技术驱动、有技术分享 / 基建投入。<br><strong>薪酬范围</strong>：X 万 ± 10%（结合市场行情）。&quot;</p></blockquote><h3 id="行业匹配" tabindex="-1">行业匹配 <a class="header-anchor" href="#行业匹配" aria-label="Permalink to &quot;行业匹配&quot;">​</a></h3><ul><li><strong>金融 / 出海 / 跨境支付</strong>：你的 SaaS / 中后台 + 安全经验有优势</li><li><strong>电商 / 营销</strong>：你的大屏 / SSR / uni-app 经验有优势</li><li><strong>AI / Agent 方向</strong>：你博客里已经在沉淀前端 + AI 集成，是稀缺过渡能力</li></ul><hr><h2 id="四、工作中有挑战的事情" tabindex="-1">四、工作中有挑战的事情？ <a class="header-anchor" href="#四、工作中有挑战的事情" aria-label="Permalink to &quot;四、工作中有挑战的事情？&quot;">​</a></h2><blockquote><p>⚠️ 这是技术面必问。建议准备 <strong>2 个</strong>：1 个技术深度 + 1 个跨团队协作。</p></blockquote><h3 id="推荐选题" tabindex="-1">推荐选题 <a class="header-anchor" href="#推荐选题" aria-label="Permalink to &quot;推荐选题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选题方向</th><th>推荐项目</th><th>重点</th></tr></thead><tbody><tr><td>技术深度</td><td>智能风控引擎 Vue 2 → Vue 3 + Vite 迁移</td><td>启动 28s → 0.8s、迁移踩坑</td></tr><tr><td>跨团队协作</td><td>商户管理 SaaS 接口契约 + 统一请求层</td><td>推动后端出 swagger、前端自动生成</td></tr><tr><td>业务复杂度</td><td>智能风控规则配置器（操作符驱动右侧控件）</td><td>设计 + 实现</td></tr><tr><td>安全加固</td><td>会员服务 三方登录 + 设备指纹 + 验证码单例</td><td>攻防思路</td></tr><tr><td>性能优化</td><td>农业数字化 App + IoT 大屏 WebSocket 管理</td><td>长连接 + 弱网</td></tr></tbody></table><h3 id="star-法则准备" tabindex="-1">STAR 法则准备 <a class="header-anchor" href="#star-法则准备" aria-label="Permalink to &quot;STAR 法则准备&quot;">​</a></h3><ul><li><strong>S</strong>ituation：项目背景 / 规模 / 复杂度（10s）</li><li><strong>T</strong>ask：你的角色 / 责任（5s）</li><li><strong>A</strong>ction：你具体做了什么（90s，重点）</li><li><strong>R</strong>esult：数据化产出（20s）</li></ul><blockquote><p>📚 项目深挖清单：<a href="./../2-复习清单#🎯-项目经验深挖清单">复习清单 §项目经验深挖清单</a></p></blockquote><hr><h2 id="五、为什么是你-你的核心竞争力" tabindex="-1">五、为什么是你 / 你的核心竞争力？ <a class="header-anchor" href="#五、为什么是你-你的核心竞争力" aria-label="Permalink to &quot;五、为什么是你 / 你的核心竞争力？&quot;">​</a></h2><blockquote><p>⚠️ 这是终面 / 高 level 面试官最常问的。</p></blockquote><h3 id="三个核心维度" tabindex="-1">三个核心维度 <a class="header-anchor" href="#三个核心维度" aria-label="Permalink to &quot;三个核心维度&quot;">​</a></h3><ol><li><strong>业务深度</strong>：B 端 SaaS / 中后台 / 跨端，7 年完整链路经验</li><li><strong>技术深度</strong>：能从源码讲清 Webpack/Vite 构建链、Vue 响应式、React Fiber</li><li><strong>工程化能力</strong>：组件库、统一请求层、性能优化可量化</li></ol><h3 id="_7-年经验差异化话术" tabindex="-1">7 年经验差异化话术 <a class="header-anchor" href="#_7-年经验差异化话术" aria-label="Permalink to &quot;7 年经验差异化话术&quot;">​</a></h3><blockquote><p>&quot;7 年里我在 4 个项目上覆盖了<strong>B 端 / C 端 / 跨端 / 大屏</strong>四种形态，最大的差异点是<strong>业务落地能力 + 工程化沉淀</strong>——不只是写组件，而是能从 0 到 1 搭一整套中后台体系（接口契约 + 组件库 + 安全加固 + 性能优化）。&quot;</p></blockquote><hr><h2 id="六、你最大的缺点是什么" tabindex="-1">六、你最大的缺点是什么？ <a class="header-anchor" href="#六、你最大的缺点是什么" aria-label="Permalink to &quot;六、你最大的缺点是什么？&quot;">​</a></h2><blockquote><p>⚠️ 压力面试高频题。</p></blockquote><h3 id="答题公式" tabindex="-1">答题公式 <a class="header-anchor" href="#答题公式" aria-label="Permalink to &quot;答题公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[真实但无关紧要的缺点] + [已经在改进 + 进展]</span></span></code></pre></div><h3 id="参考话术-1" tabindex="-1">参考话术 <a class="header-anchor" href="#参考话术-1" aria-label="Permalink to &quot;参考话术&quot;">​</a></h3><h4 id="话术-a-拖延症" tabindex="-1">话术 A（拖延症） <a class="header-anchor" href="#话术-a-拖延症" aria-label="Permalink to &quot;话术 A（拖延症）&quot;">​</a></h4><blockquote><p>&quot;我偶尔会过度追求技术完美，导致简单需求也搞得很复杂。这两年在用&quot;最小可用 + 迭代&quot;的方式克制自己，最近 3 个迭代都按时交付了。&quot;</p></blockquote><h4 id="话术-b-不擅长跨部门沟通" tabindex="-1">话术 B（不擅长跨部门沟通） <a class="header-anchor" href="#话术-b-不擅长跨部门沟通" aria-label="Permalink to &quot;话术 B（不擅长跨部门沟通）&quot;">​</a></h4><blockquote><p>&quot;我之前专注技术，对业务方需求理解不够深。后来学了<strong>业务调研 + 用户访谈</strong>，现在能独立对接运营 / 产品。&quot;</p></blockquote><h4 id="话术-c-不擅长英语" tabindex="-1">话术 C（不擅长英语） <a class="header-anchor" href="#话术-c-不擅长英语" aria-label="Permalink to &quot;话术 C（不擅长英语）&quot;">​</a></h4><blockquote><p>&quot;我英语阅读 OK，口语和写作弱一些。今年开始每周看 2 篇英文技术博客，目标 6 个月能流利地看英语技术会议视频。&quot;</p></blockquote><h3 id="❌-不要说的话-1" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话-1" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ 编造致命缺点（&quot;我太追求完美了&quot;）</li><li>❌ 优点包装成缺点（&quot;我工作太投入，经常加班&quot;）</li><li>❌ 真的暴露严重问题（&quot;我和同事合不来&quot;）</li></ul><hr><h2 id="七、你能接受加班吗" tabindex="-1">七、你能接受加班吗？ <a class="header-anchor" href="#七、你能接受加班吗" aria-label="Permalink to &quot;七、你能接受加班吗？&quot;">​</a></h2><h3 id="万能公式-3" tabindex="-1">万能公式 <a class="header-anchor" href="#万能公式-3" aria-label="Permalink to &quot;万能公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[接受合理强度] + [高效工作] + [事业心]</span></span></code></pre></div><h3 id="参考话术-2" tabindex="-1">参考话术 <a class="header-anchor" href="#参考话术-2" aria-label="Permalink to &quot;参考话术&quot;">​</a></h3><blockquote><p>&quot;我能接受<strong>阶段性高强度</strong>（比如赶版本、上线、线上故障），但更倾向于<strong>高效工作</strong>——通过流程和工具减少无效时间。我之前项目里有 3 次紧急上线经验，都能和团队一起扛下来。&quot;</p></blockquote><hr><h2 id="📌-准备清单-面试前-1-天过" tabindex="-1">📌 准备清单（面试前 1 天过） <a class="header-anchor" href="#📌-准备清单-面试前-1-天过" aria-label="Permalink to &quot;📌 准备清单（面试前 1 天过）&quot;">​</a></h2><ul><li>[ ] &quot;为什么看新机会&quot;选定 1 个话术</li><li>[ ] 去年绩效准备好具体数据</li><li>[ ] 找工作倾向（业务 / 团队 / 薪酬）准备清晰</li><li>[ ] 2 个最有挑战的事用 STAR 法则写下来</li><li>[ ] 核心竞争力准备 3 个维度</li><li>[ ] 缺点准备 1 个 + 改进方法</li><li>[ ] 加班态度准备一段</li></ul><h2 id="🔗-相关文档" tabindex="-1">🔗 相关文档 <a class="header-anchor" href="#🔗-相关文档" aria-label="Permalink to &quot;🔗 相关文档&quot;">​</a></h2><ul><li><a href="./../3-自我介绍">自我介绍（3 个版本）</a></li><li><a href="./../2-复习清单">复习清单</a></li><li><a href="./../项目/项目经验/">4 个项目经验</a></li></ul>',78)])])}const b=t(r,[["render",i]]);export{q as __pageData,b as default};
